-- v10: dados de linguagem e corpus no SQLite, aplicação única.
-- Algoritmos continuam no JS; itens abaixo são dados editáveis, não modelos de decisão.
CREATE TABLE IF NOT EXISTS semantic_terms (
 language TEXT NOT NULL DEFAULT 'pt-BR', kind TEXT NOT NULL CHECK(kind IN ('lexical','entity_alias')),
 phrase TEXT NOT NULL, canonical TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
 origin TEXT NOT NULL DEFAULT 'bootstrap', PRIMARY KEY(language,kind,phrase)
);
CREATE INDEX IF NOT EXISTS ix_semantic_terms_canonical ON semantic_terms(kind,canonical,active);
CREATE TABLE IF NOT EXISTS semantic_entities (
 entity_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, article TEXT NOT NULL DEFAULT 'de',
 active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), origin TEXT NOT NULL DEFAULT 'bootstrap'
);
CREATE TABLE IF NOT EXISTS semantic_social_cues (
 language TEXT NOT NULL DEFAULT 'pt-BR', phrase TEXT NOT NULL, intent TEXT NOT NULL,
 match_mode TEXT NOT NULL CHECK(match_mode IN ('prefix','contains','exact')),
 active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),
 PRIMARY KEY(language,phrase,intent,match_mode)
);
CREATE TABLE IF NOT EXISTS semantic_social_responses (
 language TEXT NOT NULL DEFAULT 'pt-BR', intent TEXT NOT NULL, response TEXT NOT NULL,
 active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), PRIMARY KEY(language,intent)
);
CREATE TABLE IF NOT EXISTS intent_training_samples (
 id INTEGER PRIMARY KEY AUTOINCREMENT, language TEXT NOT NULL DEFAULT 'pt-BR', label TEXT NOT NULL,
 text TEXT NOT NULL, normalized_text TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),
 origin TEXT NOT NULL DEFAULT 'bootstrap', UNIQUE(language,label,normalized_text)
);
CREATE INDEX IF NOT EXISTS ix_intent_samples_label ON intent_training_samples(label,active);
